// spec: .qa/e2e/specs/profile.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

const ORIGINAL_NAME = 'אקדא טסט';
const TEST_NAME = 'QA-AUTO-שם בדיקה';

async function setName(page: Page, name: string) {
  await page.goto('/profile');
  await page.getByRole('button', { name: 'עריכת השם' }).click();
  const dialog = page.getByRole('dialog');
  await dialog.getByRole('textbox', { name: 'שם מלא' }).fill(name);
  await dialog.getByRole('button', { name: 'שמירה' }).click();
  await expect(page.getByRole('alert').filter({ hasText: 'שם מלא: השינוי נשמר.' })).toBeVisible();
}

test.describe('Профиль — вошедший пользователь', () => {
  test('PR-02 Правка имени — видно везде, переживает reload; пустое и >60 символов не сохраняются #ba9c188c @data @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    try {
      // 1. Открыть `/profile` → «עריכת השם» → поле «שם מלא».
      await page.goto('/profile');
      await expect(page.getByRole('button', { name: 'עריכת השם' })).toContainText(ORIGINAL_NAME);
      await page.getByRole('button', { name: 'עריכת השם' }).click();
      const dialog = page.getByRole('dialog');
      const input = dialog.getByRole('textbox', { name: 'שם מלא' });
      const save = dialog.getByRole('button', { name: 'שמירה' });
      await expect(input).toHaveValue(ORIGINAL_NAME);

      // 2. Очистить поле; затем только пробелы; затем 65 символов.
      await input.fill('');
      await expect(save).toBeDisabled();
      await input.fill('     ');
      await expect(save).toBeDisabled();
      await input.fill('א'.repeat(65));
      await expect(dialog.getByText('השם ארוך מדי: אפשר עד 60 תווים.')).toBeVisible();
      await expect(save).toBeDisabled();

      // 3. Ввести «QA-AUTO-שם בדיקה» → «שמירה».
      await input.fill(TEST_NAME);
      await expect(save).toBeEnabled();
      await save.click();
      await expect(page.getByRole('alert').filter({ hasText: 'שם מלא: השינוי נשמר.' })).toBeVisible();
      await expect(page.getByRole('dialog')).toHaveCount(0);

      // 4. Reload `/profile`; открыть `/journey` и `/home`.
      await page.reload();
      await expect(page.getByRole('button', { name: 'עריכת השם' })).toContainText(TEST_NAME);
      await expect(page.getByRole('button', { name: 'העלאת תמונת פרופיל' })).toContainText('Q');
      await expect(page.getByRole('button', { name: `שם מלא: ${TEST_NAME}. מעבר לשלב כדי לשנות` })).toBeVisible();

      await page.goto('/journey');
      await expect(page.getByText(TEST_NAME, { exact: true }).first()).toBeVisible({ timeout: 20_000 });
      await dismissMilestoneIfShown(page);

      await page.goto('/home');
      await expect(page.getByText(TEST_NAME, { exact: true }).first()).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText(new RegExp(`${TEST_NAME}, מוכן לתפילה`))).toBeVisible();
    } finally {
      // 5. Уборка: вернуть «אקדא טסט»; reload `/profile` и `/home`.
      await setName(page, ORIGINAL_NAME);
      await page.reload();
      await expect(page.getByRole('button', { name: 'עריכת השם' })).toContainText(ORIGINAL_NAME);
      await page.goto('/home');
      await expect(page.getByText(new RegExp(`${ORIGINAL_NAME}, מוכן לתפילה`))).toBeVisible({ timeout: 20_000 });
    }
  });
});
